export type WritingRun = { text: string; bold?: boolean; italic?: boolean };
export type WritingParagraph = { runs: readonly WritingRun[] };

export const writingSource = {"1":[{"runs":[{"text":"When life is busy and you’re feeling stressed, try to take a walk with your toddler."}]},{"runs":[{"text":"Go to a forest if you can. Or anywhere in nature. ￼"}]},{"runs":[{"text":"Don’t bring a stroller. Don’t bring anything really (apart from snacks obviously). "}]},{"runs":[{"text":"Let your toddler choose the pace."}]},{"runs":[{"text":"It is better if you don’t have any upcoming plans, because the pace will be slow. So very slow. "}]},{"runs":[{"text":"Two steps forwards and one step back. "}]},{"runs":[{"text":"Your toddler will want to inspect everything! Turn over every leaf and stone. "}]},{"runs":[{"text":"You’ll feel the need to say, “Come on let’s keep walking!” "}]},{"runs":[{"text":"But don’t. "}]},{"runs":[{"text":"Let them do their thing. "}]},{"runs":[{"text":"They’ll pick up a leaf and bring it to you. "}]},{"runs":[{"text":"Then go back and pick up a particularly interesting stick they just passed. "}]},{"runs":[{"text":"A funny looking rock. Another rock. And another one. You’ll be asked to carry them in your pocket for their rock collection at home. A toddler can never have enough rocks apparently. "}]},{"runs":[{"text":"They’ll notice an insect crawling on the ground before them, and they’ll point and inform you of it’s existence. "}]},{"runs":[{"text":"They’ll notice a little non-edible berry on a bush and you’ll exclaim “No!! Dangerous!” As they go to grab it. And your mind will already have imagined the berry in their mouth and the rushed journey to the hospital. Because your mind is such a panicker like that. "}]},{"runs":[{"text":"You’ll feel the persistent need to pick up the pace. What is a walk if there is no purpose to it? This won’t even count as exercise! "}]},{"runs":[{"text":"You’ll feel the weight of all the things you could or should be doing, resting on your shoulders and pulsing noisily through your thoughts."}]},{"runs":[{"text":"You’ll feel inclined to reach for your phone. "}]},{"runs":[{"text":"An urge to entertain yourself with other things as your toddler is doing some precious self entertaining. Or maybe post the moment on social media. Hashtag “beautifulnature”."}]},{"runs":[{"text":"You might even feel slightly bored at the lack of stimulus in this moment."}]},{"runs":[{"text":"Even though there’s lots of it really."}]},{"runs":[{"text":"Your toddler is just must better at noticing it than you are. "}]},{"runs":[{"text":"They’ll notice the way the wind rustles at the leaves."}]},{"runs":[{"text":"They’ll hear a bird sing from a tree above and look around to find it."}]},{"runs":[{"text":"“Biiiid!“ they announce excitedly. "}]},{"runs":[{"text":"“It IS a bird, well done! It’s a blackbird! A girl blackbird actually. You can tell because she is brown! The boy blackbird is black.” You’ll explain, pleased that you know this fact."}]},{"runs":[{"text":"“Biddd!“ they’ll repeat, pleased with themselves for knowing the word."}]},{"runs":[{"text":"They’ll spot a little puddle from miles away and run as fast as their little legs can over to stomp in it until there’s barely any water left."}]},{"runs":[{"text":"They’ll suddenly bend down, pick something up and exclaim: “Hat!”"}]},{"runs":[{"text":"And you’ll crouch down to see what they are talking about. "}]},{"runs":[{"text":"They are holding an acorn and has peeled off the top of it. "}]},{"runs":[{"text":"“Oh that DOES look like a hat!” You’ll say. Feeling oddly excited about the little discovery. And the two of you collect a bunch of little acorns and take off their hats and put them on again. On and on until another piece of nature is discovered."}]},{"runs":[{"text":"If you let them, kids are amazing at helping you to stop and smell the flowers every once in a while."}]},{"runs":[{"text":"\n"}]}],"2":[{"runs":[{"text":"It was a BAD morning. ￼"}]},{"runs":[{"text":"The baby refused her breakfast."}]},{"runs":[{"text":"The toddler wanted yoghurt…no she wanted porridge…No, she wanted bread. No, actually she wanted yoghurt after all, but not the yoghurt in the fridge. She wanted another kind of yoghurt. No, she wasn’t actually hungry at all."}]},{"runs":[{"text":"I rushed to make packed lunches, with a baby hanging on to my legs, crying to be picked up and a toddler crying for my attention."}]},{"runs":[{"text":"None of them wanted clothes on."}]},{"runs":[{"text":"There was a massive poopy diaper."}]},{"runs":[{"text":"There were tears and screaming and kicking."}]},{"runs":[{"text":"I wrestled a wriggly baby and then a wriggly toddler onto the floor to get their teeth brushed. Both of them wanted to do it themselves. None of them wanted to open their mouths when I did it."}]},{"runs":[{"text":"I wrestled angry, stubborn and unhelpful limps into bulky, unhelpful autumn jackets."}]},{"runs":[{"text":"Wrestled kicking feet into shoes."}]},{"runs":[{"text":"Bounced a clingy baby on my hip while directing impatient orders at toddler with an impatient finger."}]},{"runs":[{"text":"I shouted at toddler. I apologised for shouting."}]},{"runs":[{"text":"Toddler wanted a hug."}]},{"runs":[{"text":"Baby wanted a hug."}]},{"runs":[{"text":"Mommy wanted a hug."}]},{"runs":[{"text":"And we were SO late. And there wasn’t time for the long hugs we all craved."}]},{"runs":[{"text":"I strapped them both into the double buggy and power walked to the nursery."}]},{"runs":[{"text":"Sweating and angry with myself for being so angry with my kids this morning."}]},{"runs":[{"text":"Angry for not making the packed lunches last night like I promised myself I would."}]},{"runs":[{"text":"Angry for being late yet again."}]},{"runs":[{"text":"Angry for starting off our day on so much annoyance."}]},{"runs":[{"text":"Angry for not having time to hug my kids when they needed me to hug them."}]},{"runs":[{"text":"“Mommy!” My toddler called me out of my regretful thoughts."}]},{"runs":[{"text":"“Yes love?”"}]},{"runs":[{"text":"“What a lovely day!” She exclaimed, mirroring what I would usually be saying on a day like today if I wasn’t too absorbed in my self anger."}]},{"runs":[{"text":"I looked up and noticed for the first time the blue sky and crisp air and wonderful sun and colouring autumn leaves. I could hear my baby happy babbling in her seat."}]},{"runs":[{"text":"Both kids seemed to have put the crappiness of the morning behind them."}]},{"runs":[{"text":"They had built a bridge and gotten over it."}]},{"runs":[{"text":"It was time mommy did too."}]},{"runs":[{"text":"“It IS a BEAUTIFUL day!” I agreed and smiled. Cheered up instantly by her cheerfulness."}]},{"runs":[{"text":"Stop. Breathe. Reset."}]},{"runs":[{"text":"My kids can stress me out like nobody else. On mornings like today, I’m 👌🏻 close to putting them up for adoption."}]},{"runs":[{"text":"But then they seem to have a magical ability to make it all better in an instant."}]},{"runs":[{"text":"Help me see the sun behind the clouds."}]},{"runs":[{"text":"You know… I think I’ll keep them after all. ❤️"}]},{"runs":[{"text":"\n"}]}],"3":[{"runs":[{"text":"Do you know that feeling when you're sitting by the sea on a warm summer evening?"}]},{"runs":[]},{"runs":[{"text":"With strangers and familiar faces around you."}]},{"runs":[]},{"runs":[{"text":"Everyone facing the sunset."}]},{"runs":[]},{"runs":[{"text":"And there's a sense of peace, despite the number of people."}]},{"runs":[]},{"runs":[{"text":"Those who speak do so quietly."}]},{"runs":[]},{"runs":[{"text":"Even the seagulls land silently on the water."}]},{"runs":[]},{"runs":[{"text":"As if out of respect for the moment."}]},{"runs":[]},{"runs":[{"text":"Nobody is looking at their phones."}]},{"runs":[]},{"runs":[{"text":"Nobody is listening to music."}]},{"runs":[]},{"runs":[{"text":"There's a shared understanding that nothing else is needed right now."}]},{"runs":[]},{"runs":[{"text":"A collective sigh of gratitude."}]},{"runs":[]},{"runs":[{"text":"And the sun turns to gold."}]},{"runs":[]},{"runs":[{"text":"And the gold spills out across the sea."}]},{"runs":[]},{"runs":[{"text":"Towards all of you."}]},{"runs":[]},{"runs":[{"text":"And it doesn't matter what you arrived here with."}]},{"runs":[]},{"runs":[{"text":"Right here, right now, you are all rich."}]},{"runs":[]},{"runs":[{"text":"Nature doesn't discriminate."}]},{"runs":[]},{"runs":[{"text":"There's gold for everyone."}]},{"runs":[]},{"runs":[{"text":"Tax-free, even."}]},{"runs":[]},{"runs":[{"text":"Pure magic."}]},{"runs":[]},{"runs":[{"text":"For those willing to notice it."}]},{"runs":[]},{"runs":[{"text":"And you leave the evening a little lighter than when you arrived."}]},{"runs":[]},{"runs":[{"text":"With gold in your heart and peace in your mind."}]},{"runs":[]},{"runs":[{"text":"With a nod to the others and a:"}]},{"runs":[]},{"runs":[{"text":"\"Well, wasn't that beautiful?\""}]},{"runs":[]},{"runs":[{"text":"It's good to be grateful."}]},{"runs":[]},{"runs":[{"text":"But something magical happens when we're grateful together."}]},{"runs":[{"text":"\n"}]}],"4":[{"runs":[{"text":"Do you know that feeling when you wake up in the middle of the night and it’s cold and your diaper feels heavy. And there are so many strange sounds all around you, and it’s dark and scary. And you get a hit in your head and it’s your hand that’s on its own adventure. And you can’t control it at all and it flings itself around and scratches your face and pulls at your hair. And your legs start kicking off the duvet, even though you’re cold as it is and you try to make it stop but they have their own will. And so you’re lying there completely helpless with flailing limbs that want to do everything, but none of the things you want."}]},{"runs":[{"text":"And you can’t find mom. And you call for her and you find yourself feeling really scared. What if your beloved mom doesn’t come for you. You can’t imagine anything worse and you start to cry because you miss her so terribly. You have never felt as alone as this very moment."}]},{"runs":[{"text":"And then she is suddenly there. Standing right by your bed and looking at you with worry and love. And she is the most beautiful thing you’ve ever seen. And you grin up at her with happiness and relief. You don’t think you’ve ever felt as happy as this very moment."}]},{"runs":[{"text":"And she picks you up and holds you close. And she smells like herself, and also a bit like you. Like milk and safety and love. And it’s the best smell in the whole entire world."}]},{"runs":[{"text":"And she is warm and safe and soft and her hands caress you and she feeds you and hums your favourite tune. And you love her voice. You’ve known it far longer than you’ve really known her. It has lulled you to sleep and made you laugh and calmed you when you were distressed. It is the most beautiful voice in the whole entire world. "}]},{"runs":[{"text":"And you get to lie right up against her and you feel your entire body start to warm up again. And your still cold hand starts stroking her and moves up towards her neck and accidentally scratches her. Stupid uncontrollable hand. But mom doesn’t get angry. She takes your stupid hand in hers and it turns all warm again.  And this is the best feeling in the world. Right here in mommy’s arms, with your hand in hers. Even the diaper doesn’t feel as horrible anymore."}]},{"runs":[{"text":"And you feel your eyes getting heavy and you know that everything is okay now cause mommy is here. Your mom. Your wonderful, incredible mom who always looks after you. Night and day. "}]},{"runs":[{"text":"You look up at her one last time before you fall asleep. She looks tired and her eyes are closed, and yet she is still the most magnificent thing you know. How amazing that she wants to sit here with you in this moment. How amazing that she will always sit with you for a bit when you need her to."}]},{"runs":[{"text":"You smile to yourself. How lucky you were that she became your mom. The most perfect mom anyone could have asked for."}]},{"runs":[{"text":"You knew, even before you saw her, that she would be the best thing in the world."}]},{"runs":[{"text":"Oh how you love her. Your mom."}]},{"runs":[{"text":"\n"}]}],"5":[{"runs":[{"text":"Do you know that feeling when you’re about to make dinner, but then your baby cries and you pick her up to soothe her and she is suddenly fast asleep in your arms and you could totally put her down in her bed if you were really careful, but it feels so wonderful to have her warm body pressed up against your chest. "}]},{"runs":[{"text":"The way her little hand is clutching your shirt, and her little head fits perfectly under your neck, almost like it was tailor made for exactly this purpose. "}]},{"runs":[{"text":"And you’re so very tired, but in this moment you feel an overwhelming sense of love and gratitude that she is yours and she is here, and she is safe and healthy and perfect, and that makes the tiredness feel a little less imposing, and a little bit more like an annoying but faithful old companion. "}]},{"runs":[{"text":"And there’s so many things you need to do; there’s laundry and hoovering and dishes and exercise and the one hour prep super healthy potato curry that you have procrastinated making for days now."}]},{"runs":[{"text":"But you have a whole lifetime to make a super healthy potato curry, and a whole lifetime of laundry and dishes and hoovering and exercising. "}]},{"runs":[{"text":"But your baby is only a baby for what feels like mere minutes. As a second time mom you know this too well. Shocked by how your once baby is now a four year old, who somehow still seems to fit perfectly under your chin, but very rarely ever falls asleep there any longer. "}]},{"runs":[{"text":"And so tonight you will be having frozen pizza ... again! "}]},{"runs":[{"text":"And the dishes will be left till tomorrow. "}]},{"runs":[{"text":"And the laundry pile will grow a little bigger."}]},{"runs":[{"text":"And your floor will become a little dirtier and dustier. "}]},{"runs":[{"text":"And your post natal body will continue to look post nataly."}]},{"runs":[{"text":"And that’s okay. "}]},{"runs":[{"text":"In this moment, none of that feels very important in the slightest. You’ll feel guilty about it all soon enough, but not now. "}]},{"runs":[{"text":"Right now you feel immensely content. "}]},{"runs":[{"text":"Do you know that feeling, or is it just me?"}]},{"runs":[{"text":"\n"}]}],"6":[{"runs":[{"text":"When I was a new mom, now four years ago I had THE worst flight experience to memory. "}]},{"runs":[{"text":"I was travelling alone with my 4 month old for a 6 hour flight and she was unhappy from the second we arrived at the airport."}]},{"runs":[{"text":"She was whinging as I checked in for our flight. Squirming and whining as I was trying to get us both through passport and luggage control. Unable to settle for the entire two hours we waited to board the plane. "}]},{"runs":[{"text":"I had her strapped in a baby carrier and walked around the airport for two hours straight to try to calm her down. The only time she was semi happy was if I powerwalked, hummed a tune and patted her bum, simultaneously. I was still a new mom, so I also felt entirely not confident in myself."}]},{"runs":[{"text":"I was beyond stressed and nervous by the time we had to board the plane. Fearing the absolute worst. "}]},{"runs":[{"text":"And of course, everything went wrong. She DID NOT enjoy me sitting down with her. I didn’t have an option to move around till seatbelt signs had been switched off, so I desperately tried everything to keep her from crying. "}]},{"runs":[{"text":"I tried entertaining her with all her toys. I tried putting her to sleep. I tried feeding her. I tried singing and shushing as silently as I could as to not annoy the other passengers."}]},{"runs":[{"text":"She was not having any of it. I became sweaty and stressed and desperate, none of which helped her settle in the slightest. She cried from take off and she cried and whined almost non stop for three hours, only stopping for small naps where I barely had time to breathe before it started up again. "}]},{"runs":[{"text":"I walked laps around the plane. I rocked back and forth on my feet, trying to hide in the quietest areas with the least passengers as to not annoy anyone. Hoping the sound of the plane could drown out my baby and that they wouldn’t all judge me for being such a terrible mom that I couldn’t even calm my own child."}]},{"runs":[{"text":"And then, just when I was about to crack, a fellow mother came over to me and asked me if she should walk with my baby for a bit so I could have a break."}]},{"runs":[{"text":"I burst into grateful, exhausted and sad tears. I felt upset and embarrassed that I wasn’t the one that was able to calm her down, but I knew that it was more important to take care of myself and my own needs in this moment, than look after my dignity. "}]},{"runs":[{"text":"So I accepted her offer and she took my daughter and walked laps around the plane. And of course my daughter fell asleep almost immediately. Probably from the sound of a relaxed heartbeat and the feel of an unsweaty chest. "}]},{"runs":[{"text":"And another passenger came up to me and asked if I had had a chance to eat and whether I was okay and whether I needed anything. I burst into tears again at all the kindness directed at me. The stewardesses loaded me with food and drinks and I finally had my hands free to eat and drink and go to the bathroom. My heartbeat could return to normal. "}]},{"runs":[{"text":"And the fellow mother walked around for a good hour with my child. And it was probably one of the kindest things a stranger has ever done for me. "}]},{"runs":[{"text":"It saved my sanity and made me able to tackle the remaining journey without breaking into tears (again). "}]},{"runs":[{"text":"I hope that I one day am able to pay it forward to another parent in need. "}]},{"runs":[{"text":"Empathy and kindness towards our fellow parents goes A LONG way"}]},{"runs":[{"text":"\n"}]}],"7":[{"runs":[{"text":"“Are you happy mommy?” My daughter asked me, slightly concerned."}]},{"runs":[{"text":"I must have looked sad or angry or worried."}]},{"runs":[{"text":"Was I? Am I happy? I wondered to myself."}]},{"runs":[{"text":"I’m tired. Always tired. I’m getting too little sleep, thanks to a child going through teething and sleep regression simultaneously. "}]},{"runs":[{"text":"I’m stressed at work. "}]},{"runs":[{"text":"I’m stressed at home too. "}]},{"runs":[{"text":"I have a world of coulda woulda shouldas resting heavily on my shoulders. "}]},{"runs":[{"text":"I wished I exercised more and ate better. "}]},{"runs":[{"text":"I wish I was smarter and more productive. "}]},{"runs":[{"text":"I wish I was a more present mom and wife and friend and daughter and sister and granddaughter and employee."}]},{"runs":[{"text":"Can you be truly happy, when you’re a mother of small children? "}]},{"runs":[{"text":"Research has shown again and again and again that having children reduces happiness.  Which as a mother sounds absurd."}]},{"runs":[{"text":"I love my children! Life without them would be just absurd! How dare research suggest I’m unhappy with them!"}]},{"runs":[{"text":"But they’re also stressful little additions to our lives. They are NON stop. They drain your wallet. They drain you physically and mentally. Parenting is the hardest job I’ve ever held. So I get it… sorta."}]},{"runs":[{"text":"So, am I happy right now? Sometimes yes. Sometimes I’m overwhelmed with gratitude and happiness that I’ve been so lucky."}]},{"runs":[{"text":"But mostly I feel that I’m just keeping afloat. Living on love and exhaustion and tea and sugar."}]},{"runs":[{"text":"Am I content though? "}]},{"runs":[{"text":"Yes, you know what? I think am. "}]},{"runs":[{"text":"Content sounds like such a boring word. It sounds like you’re settling. But I disagree. I think contentment is such an underrated state of being."}]},{"runs":[{"text":"I have a job, a roof over my head, two healthy children and a loving husband and food on the table. My nearest and dearest are healthy. "}]},{"runs":[{"text":"I can provide for my family, and when my daughter asks for a doll doctors practice for her birthday, I know I can get it for her without breaking the bank. "}]},{"runs":[{"text":"I am content. I am so, so content."}]},{"runs":[{"text":"And what a privilege it is to be able to say that. It really is. "}]},{"runs":[{"text":"Of course, I didn’t say all that to her. I smiled and kissed her forehead and said, “Yes love. Of course I am”."}]},{"runs":[{"text":"And she seemed content with that answer, and carried on playing."}]},{"runs":[{"text":"Content mother, content child."}]},{"runs":[{"text":"\n"}]}],"8":[{"runs":[{"text":"My husband never puts the toilet seat down."}]},{"runs":[{"text":"He never closes drawers after himself. "}]},{"runs":[{"text":"Every time I need to close the cabinet door I have to close all his drawers first- and I usually do that with an aggressive foot and muttering under my breath."}]},{"runs":[{"text":"He is terrible at putting things back when he is done using them. "}]},{"runs":[{"text":"And every time he is finished eating, he leaves the chair out. Where it stays out until I come by to place it under the dining table where it belongs."}]},{"runs":[{"text":"He never folds the blanket when he is finished sitting on the couch. And he most certainly never fluffs the pillows."}]},{"runs":[{"text":"And he wears outdoor shoes inside. "}]},{"runs":[{"text":"No matter how many times I’ve told him to please take them off."}]},{"runs":[{"text":"And somehow he always decides to shave almost immediately after I’ve cleaned the bathroom. "}]},{"runs":[{"text":"But my husband is also patient and fun and caring with our children. And with me. "}]},{"runs":[{"text":"He loves wrapping his daughters up in a blanket and bringing them outside to watch the moon and stars and sing to them.  "}]},{"runs":[{"text":"He brings in beautiful flower bouquets from the garden and places them in a vase on the living room table. "}]},{"runs":[{"text":"He is incredible at getting things done. "}]},{"runs":[{"text":"He loves lists and crossing off ‘to dos’."}]},{"runs":[{"text":"He is curious and playful and loves turning everything into a game. "}]},{"runs":[{"text":"He is amazing at buying my birthday presents and always puts a lot of thought into ensuring it’s something I really want and need. "}]},{"runs":[{"text":"He can make me laugh and does so daily. "}]},{"runs":[{"text":"When I’m upset, he knows just how to make everything feel better again."}]},{"runs":[{"text":"When I say I need help, he immediately asks what I need from him. "}]},{"runs":[{"text":"I’ve noticed that I spend longer at getting annoyed at his small list of annoying habits than I do being grateful for the endless list of wonderful things that he does for my daughters and I. "}]},{"runs":[{"text":"I’m trying to be better at saying words of appreciation when he is wonderful, and better at swallowing nags when he annoys me. Rather than constantly having to voice them. "}]},{"runs":[{"text":"He is doing the same with me. "}]},{"runs":[{"text":"It’s an active decision from both of us. "}]},{"runs":[{"text":"It is so much easier to be unhappy than to be grateful. "}]},{"runs":[{"text":"It’s so much easier to grunt and mutter under your breath at your partners imperfections, than it is to notice and appreciate their perfections. "}]},{"runs":[{"text":"Today we choose to appreciate each other."}]},{"runs":[{"text":"And we are going to try again tomorrow. "}]},{"runs":[{"text":"And the day after that. "}]},{"runs":[{"text":"Raise each other up, instead of tearing each other down."}]},{"runs":[{"text":"Like the partners we are."}]},{"runs":[{"text":"\n"}]}],"9":[{"runs":[{"text":"I am grateful."}]},{"runs":[{"text":"I am so very grateful."}]},{"runs":[{"text":"I am grateful that my children are safe."}]},{"runs":[{"text":"That they are tucked in and warm in their beds. "}]},{"runs":[{"text":"I am grateful that their bellies are full (even if it’s only with porridge). "}]},{"runs":[{"text":"I am grateful that I can provide a roof over their heads and food on the table. "}]},{"runs":[{"text":"That they never have to want for anything."}]},{"runs":[{"text":"I am grateful that they are healthy."}]},{"runs":[{"text":"I’m grateful that they are content."}]},{"runs":[{"text":"I’m grateful that all their worries can be fixed with just a hug from me. "}]},{"runs":[{"text":"I am grateful that they are so loved. "}]},{"runs":[{"text":"So much so that it oozes out of them too and onto anyone in their company. "}]},{"runs":[{"text":"I am grateful that they have a loving father and dozens and dozens of adoring family members. "}]},{"runs":[{"text":"I am grateful that they have each other. "}]},{"runs":[{"text":"I am grateful that they are mine and that I’m theirs. "}]},{"runs":[{"text":"And it’s easy to take it all for granted. "}]},{"runs":[{"text":"To forget to acknowledge all the little blessings. "}]},{"runs":[{"text":"But I am so very grateful. For all of it. "}]},{"runs":[{"text":"And may I never forget it."}]},{"runs":[{"text":"\n"}]}],"10":[{"runs":[{"text":"A few years ago my husband and I had to make an important decision about next steps in our lives."}]},{"runs":[{"text":"Should we stay in our busy 9-6pm jobs, with great salaries and savings, but a stressful everyday life."}]},{"runs":[{"text":"OR should we prioritise work life balance close to nature and family, but living on a tight budget."}]},{"runs":[{"text":"It was a hard decision, but when we really sat down and asked ourselves “money vs work life balance”, the answer was simple. "}]},{"runs":[{"text":"Particularly with a toddler and a baby on the way."}]},{"runs":[{"text":"Work life balance won over money. "}]},{"runs":[{"text":"It won over expensive holidays."}]},{"runs":[{"text":"It won over busy careers. "}]},{"runs":[{"text":"It won over bursting savings."}]},{"runs":[{"text":"Over running out the door in the mornings and spending hours committing weekly. "}]},{"runs":[{"text":"We now live in one of the consistently highest ranked countries in the world on the worklife balance and happiness scale - Denmark. "}]},{"runs":[{"text":"Our taxes are high sure, but we also have six weeks paid holidays a year. "}]},{"runs":[{"text":"37 hour work weeks. "}]},{"runs":[{"text":"12 months maternity/paternity leave."}]},{"runs":[{"text":"Free healthcare. "}]},{"runs":[{"text":"Free education."}]},{"runs":[{"text":"Childcare rates adjusted to how much you make. If you don’t make a lot, you don’t pay a lot. "}]},{"runs":[{"text":"Our children are in a nature kindergarten, which means that they spend as much time as possible outdoors, in the forest, the beach or playground. "}]},{"runs":[{"text":"They collect eggs from their own chickens. "}]},{"runs":[{"text":"They have so much quality time with their parents. "}]},{"runs":[{"text":"Whenever we find ourselves complaining that we are on a tight budget, we remind ourselves that the prioritisation we’ve made is worth much more than the extra savings we gave up on."}]},{"runs":[{"text":"Money really isn’t everything."}]},{"runs":[{"text":"Prioritising quality time with our little family while our daughters are little is something we know we will never regret."}]},{"runs":[{"text":"\n"}]}],"11":[{"runs":[{"text":"I asked myself in the shower this morning whether I would consider myself successful."}]},{"runs":[{"text":"My 15 year high school reunion is coming up next month, which probably prompted the question."}]},{"runs":[{"text":"It was a strange question to consider."}]},{"runs":[{"text":"If someone had asked me quickly on the street, I would probably have answered no."}]},{"runs":[{"text":"I am not rich. And isn’t that success?"}]},{"runs":[{"text":"But when I dig deeper, I know that I have never aspired to be rich."}]},{"runs":[{"text":"My aspirations have always been relatively simple."}]},{"runs":[{"text":"I want to live in a house that feels like home. That makes me happy to come home to."}]},{"runs":[{"text":"I want a loving husband and two wonderful children."}]},{"runs":[{"text":"I want a job with good colleagues that I like and an empathetic manager."}]},{"runs":[{"text":"I want to be able to afford one nice holiday a year, and to never worry about the next big bill."}]},{"runs":[{"text":"I want great friends. I don’t need a lot of them, as long as the ones I have are of the highest quality."}]},{"runs":[{"text":"I want to be close to my family. Both my biological and those I’ve married into."}]},{"runs":[{"text":"I want to be able to belly laugh with my partner on a random Tuesday evening over a ridiculous inside joke that only we could understand."}]},{"runs":[{"text":"I want to feel strong, mentally and physically. To constantly work to improve myself."}]},{"runs":[{"text":"I want to spend the majority of the time feeling content with my life."}]},{"runs":[{"text":"And so, by my own set of criteria, I AM successful."}]},{"runs":[{"text":"And they are the only set of criteria that matters."}]},{"runs":[{"text":"Success is subjective."}]},{"runs":[{"text":"And I am a successful woman."}]},{"runs":[{"text":"It feels so strange to think that, let alone say it out loud."}]},{"runs":[{"text":"But I am. And I am so grateful for that❤️"}]},{"runs":[{"text":"\n"}]}],"12":[{"runs":[{"text":"And you spend the majority of your life at work. Or at least it feels that way. Updating excel spreadsheets and PowerPoint presentations that barely anyone will read or care about. Even when you are not AT work, you still think about work."}]},{"runs":[{"text":"Sometimes you work later than you would like trying to perfect the wording of an email until it reaches just the right level of corporate lingo to make your human voice sound robotic."}]},{"runs":[{"text":"And you collect your kids later than you would like and wonder why in the world you keep doing that, because it doesn't even matter."}]},{"runs":[{"text":"In fact, none of what you do at work matters much. You know this because every single time there is a mass redundancy round due to 'efficiency gains thanks to AI', people are fired on the day and asked to hand in their laptops and all the work is either forgotten about or deleted and three months later, you barely remember those who left."}]},{"runs":[{"text":"You offer no real significant contribution to the world in your work. Or at least it doesn't feel that way. Though the Corporate company you work for will spend a lot of time trying to convince you otherwise. \"You're such a valued employee, helping us live up to our corporate lingo values.\""}]},{"runs":[{"text":"But you're not."}]},{"runs":[{"text":"You know you're not."}]},{"runs":[{"text":"You don't remember last time you did something that truly lit a fire inside of you. And as a result, the fire you once felt within yourself, feels dimmed.  You try to think back to when you last felt the fire. Sure, you have felt the fire plenty of times. You felt it when you fell in love. And when you became a mother. The fire exists in your personal life. This you are certain about. This you are grateful for."}]},{"runs":[{"text":"But when did you feel a fire elsewhere. When did you DO something you were truly passionate about?"}]},{"runs":[{"text":"Have you ever really done something you were passionate about? Yes, childhood obviously. When you were climbing trees and riding horses and reading endlessly. When you could spend days outside in nature. When you could spend long summer holidays just reading book after book. When you knew the soundtrack of all the greatest Disney movies by heart."}]},{"runs":[{"text":"When you believed in Santa."}]},{"runs":[{"text":"When you believed in magic."}]},{"runs":[{"text":"There was fire there. Now it's barely a flicker. You worry that one day it will burn out all together."}]},{"runs":[{"text":"\n"}]}],"13":[{"runs":[{"text":"Once in a while, you venture out onto the job market and search the open listings for other opportunities. But you never search much further than titles that sound nearly identical to the one you currently hold. Job descriptions that sound eerily familiar."}]},{"runs":[{"text":"It is not like you can change paths now. Not after 14 years.You have been cemented into your position."}]},{"runs":[{"text":"And you’ve finally reached level 6 on the Corporate ladder."}]},{"runs":[{"text":"And level 6 comes with a fancy title and a more than comfortable salary."}]},{"runs":[{"text":"It’s taken you years of sweat, blood and tears to reach level 6. That’s not entirely true. You might have perspired slightly. It wasn’t THAT hard to reach level 6. It just took a long time."}]},{"runs":[{"text":"So, you are happy on level 6. You don’t aspire to be more than level 6 either."}]},{"runs":[{"text":"Look up!"}]},{"runs":[{"text":"If you stand on your toes, you can reach the ceiling from here. It’s right there! Just like you always dreamt of."}]},{"runs":[{"text":"You are comfortable right here."}]},{"runs":[{"text":"This is the very completely objective adult definition of success."}]},{"runs":[{"text":"Okay, you might not be ENJOYING it, but you will find a blanket and a pillow, and make a way to make this very rung feel comfortable."}]},{"runs":[{"text":"Because dammit, you WILL be comfortable here."}]},{"runs":[{"text":"It doesn't matter anyways. You can't even muster up the energy to apply for anything, because it is all just the same variations of the same thing."}]},{"runs":[{"text":"And so instead you wait for the inevitable re-orgs that happens on a bi-quarterly basis."}]},{"runs":[{"text":"Where you'll likely move teams and get a new manager and things will feel fresh for a little bit before it feels stale again."}]},{"runs":[{"text":"You're not unhappy."}]},{"runs":[{"text":"You are grateful. So very grateful."}]},{"runs":[{"text":"Plenty of people are getting fired daily. Mass firings by large corporations on a quarterly basis. Plenty of people spent months and months (even years) applying for endless amount of jobs. Being rejected by AI, because their CV didn't meet the exact requirements or simply because there were already 500 other applications. Is it worse to be rejected by a computer or a person? You're not sure. You just hope you won't end up there yourself."}]},{"runs":[{"text":"So, for now, you are one of the lucky ones. You have a wonderful manager. You have wonderful colleagues. You have a flexible work life, with a great work life balance."}]},{"runs":[{"text":"Nice pay package. Job security... ish. (nothing feels secure anymore). But for now, you're semi secure. Secure enough. This level of security will have to do."}]},{"runs":[{"text":"You have no reason to be unhappy. You're not unhappy."}]},{"runs":[{"text":"You're just feeling a little grey. It's normal."}]},{"runs":[{"text":"Some days are greyer than others. Some are very light grey where you feel absolutely fine and nearly yourself, and some turn much darker, where all you want to do is nap."}]},{"runs":[{"text":"Life is just 50 shades of grey. Not in the exciting way."}]},{"runs":[{"text":"You shout too much at your kids, even though they are good kids and you love them to bits. And you kiss your husband too little and snap at him too much even though you love your marriage."}]},{"runs":[{"text":"And you don’t work out enough and feel your body getting progressively weaker from all the sitting."}]},{"runs":[{"text":"And when you collapse on the couch after kids are in bed, you feel drained from head to toe. And send your husband ‘Do not dare start conversation with me’ eyes when he brings you your tea."}]},{"runs":[{"text":"You assume this is what adulthood feels like. Grey is normal."}]},{"runs":[{"text":"So yes. You are grateful."}]},{"runs":[{"text":"Because you are indeed one of the lucky ones."}]},{"runs":[{"text":"And your salary is higher than most of your friends. Even if they are fulfilled in their jobs and making a difference for others and you're not."}]},{"runs":[{"text":"But you are offering your family a stable life. Your children never lack for anything."}]},{"runs":[{"text":"You can buy them the Barbie dreamhouse they have wished for, even though they will only play with it a few times and then inevitably spend the remaining time playing with the cardboard box it came in."}]},{"runs":[{"text":"You can go on one nice holiday a year. You can fix the car when it breaks down. You can afford leasing a second car. You can put money into savings every month, just like the reasonable girl adult you are."}]},{"runs":[{"text":"So no. You are not unhappy. You are just going through something. It's normal."}]},{"runs":[{"text":"You are normal."}]},{"runs":[{"text":"\n"}]}],"14":[{"runs":[{"text":"I was walking my dog, walking a popular coastal path near my house. It is the season of the annual school trips, which means that every time I take this particular walk these days, I always meet at least a hundred fourteen year olds. Which is also incredibly interesting to me. I like observing the group dynamics. Eavesdropping on their conversations. Trying to find out what fourteen year olds these days are doing. Feeling a deep pain when I see those that walk completely alone. There's always a few."}]},{"runs":[{"text":"On this particular day, there was a group of girls that appeared to look for eye contact with me as we walked towards each other. “Excuse me” one of the girls said, as I was near enough. “Do you know how long it will take us to get to the nearest village?” she asked. That took me off guard. I gave them an estimate, which in hindsight wasn’t a very good one. The girls thanked me and complimented me on my cute and very wet dog. I passed them feeling happy. The next generation wasn’t as badly off as I had feared."}]},{"runs":[{"text":"And then. Five minutes later, another group appeared in the distance. Except this time, they were all on their phone. All six of them. And as I came closer to them, I heard them asking their phones how long it would take to get to the nearest village. They passed me without looking up once. No one spared me or my cute, very wet dog a single glance."}]},{"runs":[{"text":"Now, their phones will undoubtedly give them a much better answer than the one I got. Absolutely no doubt. My answer was terrible and completely off. Asking your phone is a much more efficient and reliable than asking a stranger."}]},{"runs":[{"text":"But, by asking me, those girls had done the following. They had looked up. They had sought eye contact. One of them had had to gather the courage to ask me, nicely even. They had had an exchange with a stranger, and they had complimented said strangers dog in a way that made said stranger feel a little happy. This exchange will not change the world. But what about a thousand of these little exchanges? We used to rely on each other, on strangers for a lot. We used to ask someone for directions. Ask whether the bus had gone. Ask what time it was. Ask someone to take a photograph. Ask the shop assistant whether they stocked something. Ask the stranger beside us whether this was the right queue."}]},{"runs":[{"text":"Perhaps these little exchanges were constantly reminding us that we are surrounded by others. That we can approach them. That we can help each other. That we belong to the same thing."}]},{"runs":[{"text":"Now, increasingly we don’t need others for these things. What happens when we take all these little exchanges away."}]},{"runs":[{"text":"Without those connections, maybe we start losing the understanding that we are part of something bigger. And when we stop feeling part of something bigger, perhaps it becomes easier to stop caring."}]},{"runs":[{"text":"I know. That is a lot of life philosophy to put on a school trip interaction."}]},{"runs":[{"text":"\n"}]}],"15":[{"runs":[{"text":"***ou Matter***"}]},{"runs":[{"text":"*You matter, not because you are you.*"}]},{"runs":[{"text":"*You matter because you are connected to everything that is, everything that was and everything that will be.*"}]},{"runs":[{"text":"*You are one tiny part of something enormous, constantly bumping into all the other tiny parts. Affecting them. Being affected by them.*"}]},{"runs":[{"text":"*You couldn’t have been inconsequential, even if you tried. *"}]},{"runs":[{"text":"*And boy did you try. You spent your whole life trying not to matter, because you believed you couldn’t.*"}]},{"runs":[{"text":"*Silly you. *"}]},{"runs":[{"text":"*And so, if you must be consequential, which we have established that you must.*"}]},{"runs":[{"text":"*Then make it good.*"}]},{"runs":[{"text":"*Dream bigger.*"}]},{"runs":[{"text":"*Because you are BIGGER than you.*"}]},{"runs":[{"text":"*Dream that you will positively change the world.*"}]},{"runs":[{"text":"*Dream that your choices today will create a magnificent tomorrow.*"}]},{"runs":[{"text":"*Because it can.*"}]},{"runs":[{"text":"*You matter.*"}]},{"runs":[{"text":"*Holy fricking shit how much you matter.*"}]},{"runs":[{"text":"*Don’t you dare waste it.*"}]},{"runs":[{"text":"\n"}]}],"16":[{"runs":[{"text":"**Here is a thought experiment for you.&#x20;**"}]},{"runs":[]},{"runs":[{"text":"How would you live your life differently if you knew, with absolute certainty, that there was something greater than us?"}]},{"runs":[]},{"runs":[{"text":"If you knew that your life has a purpose. That you have a unique set of talents and gifts that are meant to be shared with the world. That they could make a difference."}]},{"runs":[]},{"runs":[{"text":"If you knew that you were supported as you tried to live in alignment with who you really are."}]},{"runs":[]},{"runs":[{"text":"If you knew that you were not alone. That something unseen was working behind the scenes to look after you?"}]},{"runs":[]},{"runs":[{"text":"What would you do?"}]},{"runs":[]},{"runs":[{"text":"Would you quit your job? Would you pursue something completely different?"}]},{"runs":[]},{"runs":[{"text":"Would you sing more, dance more, love more? Live more?"}]},{"runs":[]},{"runs":[{"text":"**What would you do differently if you trusted that, whatever happened next, you would find your way through it?**"}]},{"runs":[]},{"runs":[{"text":"If you truly believed you mattered, would you live your life differently?&#x20;"}]},{"runs":[]},{"runs":[{"text":"And if so, when did you stop believing that you mattered?&#x20;"}]},{"runs":[]},{"runs":[{"text":"Or maybe, different question. Did you ever believe that you truly mattered to the world?&#x20;"}]},{"runs":[]},{"runs":[{"text":"That your actions would have an actual impact in the larger scheme of things?"}]},{"runs":[]},{"runs":[{"text":"What happened?&#x20;"}]},{"runs":[]},{"runs":[{"text":"Was it that motivational quote, about how when you look up at the stars, you realise how tiny and inconsequential we humans are, and so suddenly everything doesn't feel as important anymore?&#x20;"}]},{"runs":[]},{"runs":[{"text":"Was it during elections, when it started to feel like billionaires could buy the result anyway, so what was the point of your single vote? Democracy sometimes felt like a farce."}]},{"runs":[]},{"runs":[{"text":"Was it after scrolling social media and realising how many people had a ‘bigger voice’ than you?&#x20;"}]},{"runs":[]},{"runs":[{"text":"Was it AI? When you realised how replaceable you are?"}]},{"runs":[]},{"runs":[{"text":"Was it the 'doomsday' news? That told you that humanity would either be killed off by AI or via climate change, whichever came first."}]},{"runs":[]},{"runs":[]},{"runs":[]},{"runs":[{"text":"I don’t know if I ever believed that I could change the world.&#x20;"}]},{"runs":[]},{"runs":[{"text":"I don’t need to tell you this. You know. You’ve walked in my shoes."}]},{"runs":[]},{"runs":[]},{"runs":[]},{"runs":[{"text":"I remember having a conversation with two colleagues of deep faith. When I told them that I was an atheist, they asked me, genuinely curious: “*Well who do you pray to then?”*"}]},{"runs":[]},{"runs":[{"text":"And I answered, proudly even, that I didn’t pray. That I relied on myself only.&#x20;"}]},{"runs":[]},{"runs":[{"text":"That I believed in science to take care of things. And that THAT was enough for me.&#x20;"}]},{"runs":[]},{"runs":[{"text":"I didn’t need a God to cure my diseases. I needed doctors.&#x20;"}]},{"runs":[]},{"runs":[{"text":"I didn’t need to believe in an afterlife. I just needed to believe that we should make the most of the life we were in. And not expect seconds.&#x20;"}]},{"runs":[]},{"runs":[{"text":"I didn’t need God to help save humanity. I believed humanity was plenty capable of doing that themselves. If they pulled themselves together of course.&#x20;"}]},{"runs":[]},{"runs":[{"text":"I wore my atheist cape with pride. I knew better. I was more critical than my peers. And hence, I was smarter. At least I secretly thought so to myself. I didn’t judge them. Well. Not out loud anyways. I just thought I had it better. &#x20;"}]},{"runs":[]},{"runs":[{"text":"I answered to myself. There was no higher power I felt obliged to please or disappoint. I didn’t need a religion to try to be a good person. I just tried to be a good person because it was the right thing to do.&#x20;"}]},{"runs":[]},{"runs":[{"text":"I tried to do the best I could with what I had, to leave the world a little better than I found it. Not to get into heaven, but to not be a jerk.&#x20;"}]},{"runs":[]},{"runs":[{"text":"I felt that removing religion from the equation would make life feel lighter. Fewer rules. Fewer obligations. Less guilt. Less baggage. &#x20;"}]},{"runs":[]},{"runs":[]},{"runs":[]},{"runs":[{"text":"But atheism didn’t make me feel lighter. Or safer for that matter.&#x20;"}]},{"runs":[]},{"runs":[{"text":"It only made me feel more alone.&#x20;"}]},{"runs":[]},{"runs":[{"text":"Because I may have been strong, independent woman, looking after myself and all, but there is a whole lot of crap going on in the world that was completely out of my control to manage.&#x20;"}]},{"runs":[]},{"runs":[{"text":"I remember, when I was pregnant with my first, my husband said that Elon Musk would help save the world. That people like him, brilliant, innovative, with enormous resources, would come up with the solutions needed for things like climate change and poverty. And I remember finding that comforting.&#x20;"}]},{"runs":[]},{"runs":[{"text":"Humanity would save humanity. Someone clever enough would eventually work it out, while the rest of us could carry on carrying on.&#x20;"}]},{"runs":[]},{"runs":[{"text":"By the time my daughter was seven, Elon Musk had become one of the most polarising people on the planet, and placing my faith in individual human saviours suddenly felt considerably less reassuring.&#x20;"}]},{"runs":[]},{"runs":[{"text":"If human faith in a positive future rests solely on human shoulders, hope is a fragile little thing.&#x20;"}]},{"runs":[]},{"runs":[{"text":"For me, somewhere along the way, a lack of faith had also become a lack of hope.&#x20;"}]},{"runs":[]},{"runs":[{"text":"And somewhere along the way, my lack of hope had started turning into apathy."}]},{"runs":[]},{"runs":[{"text":"Why vote?\\"}]},{"runs":[{"text":"Why recycle?\\"}]},{"runs":[{"text":"Why plant trees?\\"}]},{"runs":[{"text":"Why fight for something better?\\"}]},{"runs":[{"text":"Why do anything beyond looking after yourself and the people you love, if humanity is doomed anyway?"}]},{"runs":[]},{"runs":[{"text":"And what is life without hope? Without hope of something better, humanity might as well just lie down and wait for imminent doom.&#x20;"}]},{"runs":[]},{"runs":[{"text":"*“Oh well, AI is going to kill us anyways within a couple of years. No point worrying about my remortgage then!”*"}]},{"runs":[]},{"runs":[{"text":"Awfully bleak really.&#x20;"}]},{"runs":[]},{"runs":[{"text":"\\*"}]},{"runs":[]},{"runs":[{"text":"Now I am somewhere completely different.&#x20;"}]},{"runs":[]},{"runs":[{"text":"The inbetween. The unknown.&#x20;"}]},{"runs":[]},{"runs":[{"text":"Slightly overwhelming, because where do you even start untangling the mess that is your own faith, or lack thereof?"}]},{"runs":[]},{"runs":[{"text":"My mother has been awfully excited about my spiritual journey, because if I now believe in spirit teams and angels, then I surely also believe in God. And then she can officially prove me wrong about all the times I actively rejected religion, which I never heard the end of from her."}]},{"runs":[]},{"runs":[{"text":"My husband has been nervous watching me constantly move the line until neither of us could see it anymore. He is afraid that one day he is going to wake up next to Coraline44, who changed her name after an exciting numerology session and now prays to a tortoise.&#x20;"}]},{"runs":[]},{"runs":[{"text":"My friends smile patiently at me and say things like, “Whatever helps you, is fine by us.” But I can see that they look at me like I used to look at believers.&#x20;"}]},{"runs":[]},{"runs":[{"text":"Oh, I hate the word Believers.&#x20;"}]},{"runs":[]},{"runs":[{"text":"And I have no idea what I believe in."}]},{"runs":[]},{"runs":[{"text":"I am not entirely sure that what I believe in is God. Because it feels bigger than my old idea of God. Slight caveat: I have not read the Bible, I know embarrassingly little about the foundations and stories of most religions, and I definitely did not pay enough attention in Religious Studies. Back then, the whole concept of a God controlling everything just seemed dumb to teenage me. And if there was indeed a God, then frankly, I thought he was a bit of a jerk for letting the world go to shit.&#x20;"}]},{"runs":[]},{"runs":[{"text":"Why would there be poverty and so much death and corruption and evil? Where was the justice?&#x20;"}]},{"runs":[]},{"runs":[{"text":"If there was a God, then it was definitely a ‘he’, who wasn’t able to multi-task and could only focus on one problem at a time.&#x20;"}]},{"runs":[]},{"runs":[{"text":"As I am typing this, I am not even entirely sure what I am allowed to say about God without offending someone.&#x20;"}]},{"runs":[]},{"runs":[{"text":"And perhaps that is part of the problem for me. The word itself feels loaded. With religion. Rules. History. Conflict. Other people’s certainty about what God is and what God wants.&#x20;"}]},{"runs":[]},{"runs":[{"text":"So look. Maybe it is just the name ‘God’ that I reject.&#x20;"}]},{"runs":[]},{"runs":[{"text":"Because the word God is tangled up with Religion for me. And Religion, in my mind, is tangled up with judgement, division, war and an awful lot of human suffering."}]},{"runs":[]},{"runs":[{"text":"But at the same time, what I have experienced and felt, feels like it requires a different understanding of life than the understanding I previously held. And I don’t feel quite clever enough to make sense of it.&#x20;"}]},{"runs":[]},{"runs":[{"text":"Because if I believe that I can receive feathers and angel numbers if and when I ask for it, what does that mean? Does the Universe realign itself to me? Am I that powerful?"}]},{"runs":[]},{"runs":[{"text":"I asked Reddit. Because these types of questions require Reddit answers. One Reddit user told me that it was entirely self-centered to believe that the Universe would realign itself around one human’s needs. How egotistical did you have to be to believe reality shaped itself around your thoughts? That other beings and things would change for YOU."}]},{"runs":[]},{"runs":[{"text":"I don’t know if it was a he. I assume. It had a ‘he’ energy to it.&#x20;"}]},{"runs":[]},{"runs":[{"text":"I have to admit that this made me feel rather guilty, because it was true. I had believed myself to be special. Unique. When my cards asked me to dream bigger and bigger and bigger still, I had felt something warm radiate through me. Because it felt like my cards REALLY believed in me. Like I was the chosen one or something. And, uff, that felt nice. THE CHOSEN ONE."}]},{"runs":[]},{"runs":[{"text":"In a world of six billion people, it felt lovely to feel special.&#x20;"}]},{"runs":[]},{"runs":[{"text":"But the question bothered me. Reddit Man did have a point."}]},{"runs":[]},{"runs":[{"text":"Why would the Universe go out of its way for teeny tiny insignificant humans. Unless... there is something about the whole ‘God is us’ and ‘we are all connected’ concept.&#x20;"}]},{"runs":[]},{"runs":[{"text":"Okay. Hear me out. Give me benefit of the doubt. Okay?&#x20;"}]},{"runs":[]},{"runs":[{"text":"We’ve come this far together. Don’t abandon me now.&#x20;"}]},{"runs":[]},{"runs":[{"text":"What if instead of talking about God. With all the baggage that comes with that name, we call it something completely different. Start over.&#x20;"}]},{"runs":[]},{"runs":[{"text":"Blank slate."}]},{"runs":[]},{"runs":[{"text":"We will call it something relatable. I say ‘We’ cause you’re in this with me now. You know you are.&#x20;"}]},{"runs":[]},{"runs":[{"text":"Maybe if we start blank slate, it will be easier for us to digest the concept of something greater than us."}]},{"runs":[]},{"runs":[{"text":"Maybe if we give it a friendly name. A feminine name of course, because if you want anything done right, put a woman in charge of it. Now that might not work with my earlier lack of multi-tasking skills comment, but we will work with that later.&#x20;"}]},{"runs":[]},{"runs":[{"text":"A name of someone who would genuinely want to be helpful. Someone who brings cakes and chicken soup when you‘re sick. And who knows everyone's’ names and birthdays and is the first to organise flowers. And who always smiles at everyone and anyone. And genuinely asks *‘How are you doing, dear?’.&#x20;*"}]},{"runs":[]},{"runs":[{"text":"And stays for the answer.&#x20;"}]},{"runs":[]},{"runs":[{"text":"Hilda. We will call the Universe Hilda.&#x20;"}]},{"runs":[]},{"runs":[{"text":"So, for the purposes of this little theory...."}]},{"runs":[]},{"runs":[{"text":"Hilda is the Universe.&#x20;"}]},{"runs":[]},{"runs":[{"text":"Hilda is everything.&#x20;"}]},{"runs":[]},{"runs":[{"text":"Hilda is everyone.&#x20;"}]},{"runs":[]},{"runs":[{"text":"We are all just little pieces of Hilda.&#x20;"}]},{"runs":[]},{"runs":[{"text":"And so Hilda can put out little feathers.\\"}]},{"runs":[{"text":"Not specifically for me. Or for you.\\"}]},{"runs":[{"text":"This isn't really about me. Or you for that matter. That is perhaps where I went wrong all along. It was never really about me. Or it was, but not in the way I believed."}]},{"runs":[]},{"runs":[{"text":"Because I AM Hilda."}]},{"runs":[]},{"runs":[{"text":"You are Hilda.&#x20;"}]},{"runs":[]},{"runs":[{"text":"The feather is Hilda.\\"}]},{"runs":[{"text":"The bird that dropped the feather is Hilda.\\"}]},{"runs":[{"text":"Me noticing the feather is Hilda. You looking skeptically at this sentence, is Hilda."}]},{"runs":[]},{"runs":[{"text":"And Hilda wants the best for all her little Hildas. Because they are her. She is good like that. Or self-involved. Whichever way you choose to see it.&#x20;"}]},{"runs":[]},{"runs":[{"text":"And so Hilda creates through all her little Hildas.\\"}]},{"runs":[{"text":"Some Hildas write music that inspires other Hildas to write.\\"}]},{"runs":[{"text":"And something they write inspires another Hilda to run for office.&#x20;"}]},{"runs":[]},{"runs":[{"text":"Or look after nature.&#x20;"}]},{"runs":[]},{"runs":[{"text":"Or simply be kinder to the Hilda standing next to them.\\"}]},{"runs":[{"text":"And on and on it goes."}]},{"runs":[]},{"runs":[{"text":"Maybe.&#x20;"}]},{"runs":[]},{"runs":[{"text":"My head hurts.&#x20;"}]},{"runs":[]},{"runs":[{"text":"So Hilda’s head hurts. And technically yours does too. On some level.&#x20;"}]},{"runs":[]},{"runs":[{"text":"It’s a theory. I am working on it.&#x20;"}]},{"runs":[{"text":"\n"}]}],"17":[{"runs":[{"text":"In this moment, you and I are connected by these words. They used to live inside of me. And now they are yours. For the taking. You may mock them. You may be moved by them. You may print them out and hang them on your wall. You may let them get absorbed into you and carry parts of them forward."}]},{"runs":[{"text":"You may do whatever you choose with them, but regardless, you reading these words connect us. "}]},{"runs":[{"text":"Isn’t that beautiful? "}]},{"runs":[{"text":"I think so. But then again, I’ve become very sensitive over the past few weeks. I find a lot of things beautiful that I didn’t used to find beautiful. Today I cried because of a song. Yesterday I felt emotional as I watched a caterpillar slowly cross my path, because I felt like it symbolised me. "}]},{"runs":[{"text":"Regardless. I find it beautiful. I hope you do too."}]},{"runs":[]},{"runs":[{"text":"A long time ago, I started a little game with myself. The game premise was simple. "}]},{"runs":[{"text":"I would try to catch the eyes of strangers and I would smile as genuinely as I could at them. I scored points if I were able to make them smile back at me. If I could make a stranger laugh, holy shit. I won the lottery. "}]},{"runs":[{"text":"I loved this game. I loved the kick of seeing strangers give me a genuine smile back. A genuine smile reaches the eyes. It is all IN the eyes. "}]},{"runs":[{"text":"In those moments, I felt like I had made a brief connection with someone else. Even if it only lasted for a few seconds. It touched my heart. I hoped it touched theirs too. I hoped that it would settle itself into them, so that perhaps they too would smile a little more at the strangers that they met. I never knew if this was the case, but I hoped. "}]},{"runs":[{"text":"The game has become increasingly difficult to carry out. Whenever I am in public places, I struggle to capture the gaze of others. Everyone is looking down. "}]},{"runs":[{"text":"Scrolling away on their phones. I have sometimes pondered what has held their attention so. When I rudely look over their shoulder, it both fascinates and disturbs me. The speed of the scroll. The meaninglessness of the content."}]},{"runs":[{"text":"I feared that those little moments of random connections would erode in humanity. It felt like I was watching the decay of our connection in real-time. "}]},{"runs":[{"text":"But if you are reading this, I have a little hope. Look at how far you’ve stayed with me. "}]},{"runs":[{"text":"I hope I have made you smile along the way. Oh, how I hope I’ve made you laugh, even if just once. "}]},{"runs":[{"text":"That would make me happy."}]},{"runs":[{"text":"\n"}]}],"18":[{"runs":[{"text":"There are many things that I have allowed to rule my life when I really think about it."}]},{"runs":[{"text":"I am currently on month three of a news detox. Which has required me to stay away from all news sources. Newspapers, podcasts, radio, social media. My beloved late night shows. It has all been eradicated from my life with a snap of a finger. At first I felt guilt. It felt very anti adult to not be informed. I would wake up in the morning and itch to find out what war had been started, ended and started again while I had slept. What evil, corruption, death, war, crisis, climate disaster had transpired while I had been away. "}]},{"runs":[{"text":"But as the weeks passed, I realised something else. Removing myself from the news of the world had freed me. I had removed its power over me and my mental health.  "}]},{"runs":[{"text":"I told an acquaintance of my strategy and he responded that I wouldn’t be able to hide from the world forever. True. Neither is that my intention. "}]},{"runs":[{"text":"The truth is, I have spent way too many years focusing on something that I had no control over, while ignoring the things that I could control. "}]},{"runs":[{"text":"Paying attention to what drained me, instead of what filled me up.  "}]},{"runs":[{"text":"Sighing over all the things that was wrong in the world, instead of asking what was in my power to make better."}]},{"runs":[{"text":"I am talking about all the tiny beautiful moments in life that I have neglected to observe, admire or be grateful for, because I wasn’t fully present. It saddens me. How much beauty was ignored, because of other things. Ironically, I am writing this with a gorgeous sunset in my back. I can feel it, warming my back. I see the glare of it on my wall. I have actually cursed it for putting a glare on my screen so I can’t properly make out what I write. "}]},{"runs":[{"text":"Cursing at beauty while writing about not appreciating beauty. "}]},{"runs":[{"text":"But I am in the flow. And not even sunsets should interrupt flow states. Are you aware of how many years I have longed for finding a flow in anything. And here I am flowing in the flow. There shall be plenty of sunsets, but flow states are precious and everything else must drop when they arrive. Because they arrive suddenly and you never know for how long they last. Which means that I served my children frozen pizza and watermelon for dinner and asked them to piss off outside and not to slam the door on their way out and “"},{"text":"Jesus christ for the love of God, what did I say about slamming the doors???”. ","italic":true}]},{"runs":[{"text":"A","italic":true},{"text":"nd here I am sitting in stillness, and there is pigeon coo’ing peacefully in a tree right outside my window, and I hear the chatter of my children playing dutifully outside. I hear their giggles and their glorious pretend play. And I think to myself, this here, is magic. "}]},{"runs":[{"text":"This here is a moment I will remember years from now. When my kids are all grown up. "}]},{"runs":[{"text":"I am rich because I am here right now, with this background chatter. A cup of tea that is still hot and a flow state that won’t stop flowing. And fingers that cannot type fast enough to keep up with the flow. "}]},{"runs":[{"text":"\n"}]}],"19":[{"runs":[{"text":"I have spent a lot of my life believing that abundance is money. The problem was that I never felt like I had enough money to classify myself as ‘abundant’. Money was an internal worry for me, even when I had more than enough to live a comfortable life. "}]},{"runs":[{"text":"I have spent a lot of time over the past few months trying to understand when and how money became such a blocker for me. "}]},{"runs":[{"text":"My earliest childhood memory related to money was when I was around seven. At this time in my life, my parents were in a lot of debt. Money was tight. They were working relentlessly. They fought a lot. They were always stressed. I remember hearing the arguments, I remember the tension. I probably didn’t understand why though. "}]},{"runs":[{"text":"On this day, my mother, brother and I were going to the beach. It was a warm summers day. At the beginning of the beach trip, my mom gave me a golden coin. It was worth enough money to be able to buy three generous ice creams at the end of our beach trip. "}]},{"runs":[{"text":"“Please look after this, so we can have ice cream afterwards.","italic":true},{"text":"” she said. I’m not sure why she gave it to me. I was a responsible child. I would often remind her to bring her wallet, when she left it by the counter. Or know where she put her keys. So maybe that is why. She trusted me to keep the coin safe. I knew that the sand made this task slightly trickier, so I identified that of all the places I could put the coin, my shoe would surely be the best place of them all. I tucked it into the toe of the shoe and placed the shoe carefully on the sand. Here it would be safe. We all happily jumped into the ocean and played and had a glorious afternoon. It was one of those spur of the moment ‘should we go to the beach’ trips that my mother had suggested after picking us up from school. It felt special and magical and fun. "}]},{"runs":[{"text":"However, when we came back to the car from the beach, and my mom asked for the coin, it was gone. My heart sank. I must have dropped it on the way back to the car. She was furious. I was heartbroken and felt a deep sense of failure. We left the beach without any ice cream. My brother and I crying, my mother driving away in angry silence. I felt responsible for turning a wonderful promising afternoon into disaster. It was a terrible burden to carry in a little body. "}]},{"runs":[{"text":"Though my parents turned their financial situation around and our family moved from poor to middle class, money has throughout my entire life been something that I have struggled to find a good relationship with. "}]},{"runs":[{"text":"Money was always on my mind when I was in university and didn’t know if I had enough to take me till the end of the month. "}]},{"runs":[{"text":"It was always on my mind when I was a waitress and would save to pay the bills. "}]},{"runs":[{"text":"And then, when I finally entered real adulthood with real adult pay, money still became a constant concern. Because despite the fact that I suddenly had enough, I always worried about all the ‘What ifs’. All the future made up potential catastrophies that would cause financial instability: "}]},{"runs":[{"text":"‘What if I lost my job... then I wouldn’t have enough.’","italic":true}]},{"runs":[{"text":"“What if I lose my job AND THEN my husband loses his too! Terrible!”","italic":true}]},{"runs":[{"text":"“What if suddenly the roof needed fixing. Then it would be tight. “","italic":true}]},{"runs":[{"text":"Money was a constant source of worry. And so, I constantly chased it. Worried about it. Checked my accounts. My stocks. Panicked when too much money was going out. I had budget excel spreadsheets. I had a budget on top of a budget. I knew the exact days money would come in, and I found satisfaction waking up and seeing my pay arrive in my account on payday. And then immediate stress at seeing the amount of money that would soon flow out from upcoming scheduled bills. "}]},{"runs":[{"text":"I would feel a sense of pride when my pay increased. Because it felt like my worth increased with it. A big bonus? Oh, look how valuable I am!"}]},{"runs":[{"text":"I was stingy about the money that I did have. Not for others, I didn’t want to be stingy for others, I had been taught better than that. But stingy towards myself. I would wear shoes until they would fall apart and take ages buying anything, because it felt excessive."}]},{"runs":[{"text":"I was a greedy git, but it wasn’t because I wasn’t grateful for what I have right now. "}]},{"runs":[{"text":"It was because of a deep underlying fear that I wouldn’t have enough tomorrow."}]},{"runs":[{"text":"Because I am extremely abundant. I am. I know this. I do. "}]},{"runs":[{"text":"Somewhere along the way, money had become THE THING that ran my life. "}]},{"runs":[{"text":"And this fricking THING dictated my life. It determined whether I felt safe. Secure. Content. Whether I could leave my job. Whether I could take a risk. Whether I had enough. Whether I was enough. I have spent my entire life working in corporate, not because I enjoyed it, but because I feared not having THE THING. Because I connected my own value with THE THING."}]},{"runs":[{"text":"What a load of bull."}]},{"runs":[{"text":"Seriously. What a load of absolute garbage. "}]},{"runs":[{"text":"And this stops here. "}]},{"runs":[{"text":"Dearest Money. ","italic":true}]},{"runs":[{"text":"Fuck ever so much off!","italic":true}]},{"runs":[{"text":"Seriously!","italic":true}]},{"runs":[{"text":"No, not really, because I need you still. ","italic":true}]},{"runs":[{"text":"But metaphorically speaking. ","italic":true}]},{"runs":[{"text":"I need you, but I can also be rich without you. ","italic":true}]},{"runs":[{"text":" You may be powerful, but you do not get to dictate my life. ","italic":true}]},{"runs":[{"text":"Anymore.","italic":true}]},{"runs":[{"text":"At least not like you have. ","italic":true}]},{"runs":[{"text":"I am setting boundaries between us. ","italic":true}]},{"runs":[{"text":"Starting now.","italic":true}]},{"runs":[{"text":"So piss off my friend. ","italic":true}]},{"runs":[{"text":"Also, don’t piss off too far. ","italic":true}]},{"runs":[{"text":"It’s complicated.","italic":true}]},{"runs":[{"text":"I’m working on it. ","italic":true}]},{"runs":[{"text":"Thank you","italic":true}]},{"runs":[{"text":"I am on fire (metaphorically), my tea is hot (literally) and my children are giggling, in far enough proximity to me that I can let myself flow and "},{"text":"“WHAT DID I SAY ABOUT SLAMMING THE DOORS!”","bold":true}]},{"runs":[{"text":"Rich, I tell you."}]},{"runs":[{"text":"\n"}]}],"20":[{"runs":[{"text":"\"Quit. Go back to studying psychology.\"","italic":true}]},{"runs":[{"text":"You hear it, not as a voice. But as a deep knowing. "}]},{"runs":[{"text":"It comes while you are watching your children on the swings."}]},{"runs":[{"text":"The deep knowing comes from somewhere that is you and yet doesn't feel like you. It comes with a certainty that you have not experienced before. It is not a question. It's an order."}]},{"runs":[{"text":"When you say it out loud, you start to cry. Sob. Your body suddenly feels relief. It is like a mini explosion deep within. You feel waves of intense relief flooding through you. "}]},{"runs":[{"text":"That is the answer that you have unknowingly been searching for. "}]},{"runs":[{"text":"You feel no fear. Even though there objectively should be plenty worth fearing. Quitting a stable job is reckless at best. Stupid at worst. "}]},{"runs":[{"text":"And yet, you feel a blanket of peace fall over you. "}]},{"runs":[{"text":"Epiphany?"}]},{"runs":[{"text":"Enlightenment?"}]},{"runs":[{"text":"Moment of spiritual awakening?"}]},{"runs":[{"text":"You try out different explanations on your tongue. To try to explain what you just experienced. "}]},{"runs":[{"text":"This wasn't something you could prove. Only something you suddenly knew."}]},{"runs":[{"text":"Of course, there was one obstacle before you could just... LEAP. "}]},{"runs":[{"text":"Your husband. Your rational, very atheist husband. But who might be slightly less accommodating to his wife quitting her job based on a ‘feeling’. Who might question how his wife, who just two weeks ago said that she would never, ever, ever want to go back to studying, is now saying that she absolutely has to study a subject with unknown and probably difficult future career paths, because an inner voice told her to on a park bench. "}]},{"runs":[{"text":"It’s a hard sell. You are in a financially stable situation. You have savings. You can buy things when you want to buy them. Going down to one salary would be doable, but tight. You would have to budget and take from your hard earned savings to get by. "}]},{"runs":[{"text":"And you are not guaranteed a job at the other end. In fact, you don’t even know what that job would look like, if it even existed. "}]},{"runs":[{"text":"This could quite easily be the biggest career mistake of your life. You could sit a year from now and curse Past You and her ridiculous impulses based on nothing but ‘a feeling’. All because she was in a ‘spirituality’ phase for a bit. Because who in the world quits their job based on ‘a feeling’. With no guarantees or security or promises. "}]},{"runs":[{"text":"And you are not just leaping into the unknown by yourself, you are taking your family along for the ride. For the good, for the bad, for the ugly. You will not be able to take the fancy holidays you had planned. You will not be able to eat out as often anymore. "}]},{"runs":[{"text":"And so, you choose your timing wisely. Catching him just as he has poured boiling water into two cups for tea. When it comes to the Irish, important conversations must always be held over a cup of tea. Or Guinness. Depending on the time of day. "}]},{"runs":[{"text":"And you ask him how he would feel if you, say, quit your job to study psychology again. And he looks questioning at you, but asks calmly what you expect to become. Where is this path going. "}]},{"runs":[{"text":"And you tell him that you don’t know. But that you feel a deep inner call to go on it. "}]},{"runs":[{"text":"And he asks you if you want to research first. Maybe talk to some people in the field. And you say that you do not. Because you are certain that this is the right thing to do. "}]},{"runs":[{"text":"And he asks if you are sure. Really sure. Because finances will be tight and it is a big decision to make for our family. And you say that you are. "}]},{"runs":[{"text":"‘Okay then. Go for it. Quit!’","italic":true},{"text":" he says, as he hugs you. The tea hasn’t even finished brewing by the time he has given you his support. "}]},{"runs":[{"text":"And you burst into tears. Not because you didn’t believe he would support you. Of course he would. But because having him on your side, having him trusting you enough to leap into the unknown with no guarantees, feels... no. There are no words. "}]},{"runs":[{"text":"So epiphany, spiritual awakening, moment of enlightenment. It didn't really matter what you chose to call it, it only mattered how you chose to respond. Would you put on your big-girl pants and oblige?"}]},{"runs":[{"text":"Of course you do. You may be just an average woman. But you ain't no wuss. "}]},{"runs":[{"text":"And so, you trust."}]},{"runs":[{"text":"And so, you leap."}]},{"runs":[{"text":"The very next day you send your application to university. "}]},{"runs":[{"text":"Two weeks later, you quit your job. Just like that."}]},{"runs":[{"text":"\n"}]}]} as const satisfies Record<number, readonly WritingParagraph[]>;

export const goldForEveryoneDanish = [{"runs":[{"text":"Kender I det, når man sidder ved havet en lun sommeraften."}]},{"runs":[{"text":"Med fremmede og bekendte omkring én. "}]},{"runs":[{"text":"Alle vendt mod solnedgangen."}]},{"runs":[{"text":"Og der er en ro, trods mængden af mennesker."}]},{"runs":[{"text":"De der taler, gør det stille."}]},{"runs":[{"text":"Selv mågerne lander uden lyd på havet. "}]},{"runs":[{"text":"Som i respekt for øjeblikket."}]},{"runs":[{"text":"Ingen kigger på telefoner."}]},{"runs":[{"text":"Ingen hører musik."}]},{"runs":[{"text":"Der er en fælles forståelse af, at der er intet andet, der skal til lige nu. "}]},{"runs":[{"text":"Et kollektivt taknemmeligt suk."}]},{"runs":[{"text":"Og solen forvandles til guld."}]},{"runs":[{"text":"Og guldet flyder ud over havet."}]},{"runs":[{"text":"Mod jer alle."}]},{"runs":[{"text":"Og det er ligegyldigt, hvad du kom hertil med. "}]},{"runs":[{"text":"Lige her og nu er I alle rige."}]},{"runs":[{"text":"Naturen diskriminerer ikke. "}]},{"runs":[{"text":"Der er guld til alle. "}]},{"runs":[{"text":"Skattefrit endda."}]},{"runs":[{"text":"Ren magi."}]},{"runs":[{"text":"Til dem, der er villige til at lægge mærke til det. "}]},{"runs":[{"text":"Og du forlader aftenen, lidt lettere end da du kom."}]},{"runs":[{"text":"Med guld i hjertet og ro i sindet."}]},{"runs":[{"text":"Med et nik til de andre og et:"}]},{"runs":[{"text":"“Jamen hvor var det smukt, hva’?”"}]},{"runs":[{"text":"Det er godt at være taknemmelig."}]},{"runs":[{"text":"Men der sker noget magisk, når man er taknemmelig sammen."}]}] as const satisfies readonly WritingParagraph[];
